"""Eckmann lowercase, hand drawn in knots. Standard parts: the brush stem (flared both ends, waisted),
the arch that grows out of the stem top, two bowls, the brush hook terminal."""
from core import K
X = 498
def stem(x, y0=0, y1=X, top=1.3, bot=1.8, lean=0, cut=(True, True)):
    m = (y0 + y1) / 2
    return K((x + lean, y0, 90, bot), (x + lean * .7, y0 + .14 * (y1 - y0), 90, 1.3), (x + lean * .4, y0 + .3 * (y1 - y0), 90, 1.05), (x, m, 90, 1.0), (x - lean * .2, y1 - .2 * (y1 - y0), 90, 1.05), (x - lean * .3, y1, 90, top), cut=cut)
def asc(x, y1=698, lean=8):                 # ascender: one brush stroke, its top a slanted wedge rising to the right
    return [K((x + lean, 0, 90, 1.8), (x + lean * .7, 90, 90, 1.3), (x + lean * .4, 200, 90, 1.05), (x, 380, 90, 1.0), (x - 2, 580, 88, 1.08), (x + 12, 660, 70, .95), (x + 58, 698, 35, .32), cut=(True, False))]
def arch(x0, x1, top=X, foot=1.5):          # grows out of the left stem top, thick over the top, down into the right stem
    return K((x0 - 45, top - 30, 40, .5), (x0 + 70, top - 25, 10, .65), ((x0 + x1) / 2 + 25, top - 35, -15, .62), (x1, top - 140, -88, 1.05), (x1 + 4, 220, -90, 1.0), (x1 + 15, 0, -80, foot), cut=(False, True))
def bowl_l(xs, xl, top=X):                  # d / q / a / g bowl: thin top out of the stem, thick round left side, thin back in
    return K((xs - 30, top - 30, 160, .45), ((xs + xl) / 2 + 10, top - 22, 180, .55), (xl + 55, 280, -95, 1.05), ((xs + xl) / 2 + 20, 55, -10, 1.3), (xs - 30, 90, 40, .55))
def bowl_r(xs, xr, top=X):                  # b / p bowl
    return K((xs + 30, top - 60, 40, .5), ((xs + xr) / 2, top - 25, 0, .62), (xr - 52, 250, -90, 1.0), ((xs + xr) / 2 - 10, 40, 200, 1.1), (xs + 20, 40, 170, .6))
def build():
    G = {}
    G["i"] = [stem(116, 0, 470, top=1.25), K((60, 470, 30, .5), (118, 490, 0, .9), (180, 470, -30, .5)), K((75, 585, 30, .7), (122, 610, 10, 1.0), (165, 625, 20, .5))]
    G["l"] = asc(100)
    G["n"] = [stem(110, 0, 470, top=1.3), arch(110, 322)]
    G["h"] = asc(112) + [arch(112, 345)]
    G["m"] = [stem(118, 0, 470, top=1.3), arch(118, 316, foot=1.35), arch(316, 515, foot=1.5)]
    G["r"] = [stem(130, 0, 470, top=1.3, bot=1.9), K((95, 450, 40, .5), (200, 465, 10, .7), (265, 470, 0, .8), (310, 450, -30, .6))]
    G["u"] = [K((118, X, -90, 1.4), (120, 300, -90, 1.0), (140, 120, -80, 1.1), (210, 60, -20, .6), (300, 150, 60, .5), cut=(True, False)), stem(350, 0, X, top=1.35, bot=1.3)]
    G["o"] = [K((200, 465, 180, .55), (65, 250, -95, 1.0), (180, 55, -10, 1.4), (320, 260, 85, .8), (240, 470, 160, .6), (200, 465, 180, .55))]
    G["c"] = [K((310, 440, 60, .5), (230, 470, 180, .7), (70, 280, -100, .95), (170, 60, -10, 1.3), (290, 85, 30, .6), (330, 130, 60, .3))]
    G["e"] = [K((70, 220, 10, .55), (230, 255, 10, .65), (300, 320, 80, .8), (230, 455, 160, .65), (70, 280, -100, .95), (170, 60, -10, 1.3), (300, 85, 30, .6), (340, 140, 60, .3))]
    G["a"] = [stem(330, 0, X, top=1.0, bot=1.5), bowl_l(330, 21)]
    G["d"] = [stem(332, 0, 600, top=1.15, bot=1.5, cut=(True, False)), K((320, 590, 90, 1.15), (335, 650, 75, .95), (380, 698, 40, .3)), bowl_l(332, 20)]
    G["q"] = [stem(318, -160, X, top=1.1, bot=1.3), bowl_l(318, 12)]
    G["g"] = [K((320, X, -90, 1.1), (322, 100, -90, 1.0), (300, -60, -100, 1.0), (200, -125, 200, .9), (100, -90, 150, .6), cut=(True, False)), bowl_l(320, 15)]
    G["b"] = asc(102) + [K((102, 600, -90, 1), (102, 60, -90, 1.05), (110, 0, -90, 1.6), cut=(False, True)), bowl_r(102, 406)]
    G["p"] = [stem(112, -160, X, top=1.4, bot=1.6), bowl_r(112, 428)]
    G["f"] = [stem(86, 0, 560, top=1.0, cut=(True, False)), K((80, 550, 90, 1.0), (120, 650, 45, .9), (180, 685, 10, .55), (200, 660, -60, .4)), K((25, 455, 0, .6), (110, 460, 0, .55), (205, 450, -10, .45))]
    G["t"] = [stem(107, 0, 500, top=1.0, cut=(True, False)), K((107, 490, 90, 1.0), (140, 600, 70, .6), (160, 670, 80, .3)), K((15, 460, 10, .6), (120, 465, 0, .6), (238, 455, -10, .5))]
    G["j"] = [K((128, 470, -90, 1.35), (130, 150, -90, 1.0), (110, 0, -110, 1.0), (40, -80, 210, .8), (-15, -90, 200, .3), cut=(True, False)), K((60, 470, 30, .5), (128, 490, 0, .9), (190, 470, -30, .5)), K((92, 555, 30, .7), (136, 585, 10, 1.0), (180, 600, 20, .5))]
    G["k"] = asc(112) + [K((290, 480, 220, .5), (230, 330, 230, .75), (150, 250, 200, .4)), K((210, 270, -40, .8), (330, 90, -55, 1.15), (420, 0, -40, 1.3), cut=(False, True))]
    G["s"] = [K((300, 460, 120, .45), (190, 485, 180, .75), (60, 400, -90, .9), (160, 250, -30, 1.15), (260, 170, -80, 1.1), (170, 30, 200, .9), (50, 70, 130, .55), (30, 110, 120, .3))]
    G["v"] = [K((110, X, -90, 1.6), (140, 250, -85, 1.0), (180, 60, -60, .8), (270, 20, 20, .6), (380, 200, 75, .9), (400, 350, 90, 1.0), (390, X, 95, 1.1), cut=(True, True))]
    G["w"] = [K((110, X, -90, 1.6), (140, 250, -85, 1.0), (180, 60, -60, .75), (270, 60, 50, .55), (330, 260, 80, .8), (350, 400, 90, .9)),
              K((330, 260, -75, .8), (430, 50, -40, .7), (520, 150, 70, .85), (560, 330, 85, 1.0), (560, X, 95, 1.1), cut=(False, True))]
    G["x"] = [K((120, X, -60, 1.5), (250, 250, -62, .95), (370, 0, -60, 1.5), cut=(True, True)), K((380, X, -120, 1.3), (230, 230, -125, .55), (90, 0, -115, 1.4), cut=(True, True))]
    G["y"] = [K((110, X, -90, 1.5), (140, 250, -85, 1.0), (190, 90, -60, .8), (300, 100, 40, .6)), K((370, X, -90, 1.3), (365, 200, -90, 1.05), (330, 0, -100, 1.0), (240, -110, 200, .8), (150, -100, 170, .3), cut=(True, False))]
    G["z"] = [K((90, 470, 10, .7), (250, 480, 0, .75), (400, 480, 5, .6)), K((390, 470, -130, .5), (230, 280, -128, .55), (60, 50, -128, .9)), K((30, 30, 0, .9), (200, 40, 0, 1.0), (360, 60, 30, .9), (400, 130, 90, .4))]
    return G
